    stack->capacity = initial_capacity;
    stack->top = -1;
    stack->arrPtr = malloc(initial_capacity * sizeof(int));
    if (stack->arrPtr == NULL) {
        free(stack);
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        int value = min_value + rand() % (max_value - min_value + 1);
        push(stack, value);
    }
    return stack;
}

